#!/usr/bin/env node
// Zero-dependency CSV summarizer: sums `amount` by `category` and computes the total.
// Usage: node outputs/summarize.mjs [input.csv] [output.json]

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const inputPath = resolve(process.argv[2] ?? 'uploads/sample.csv');
const outputPath = resolve(process.argv[3] ?? 'outputs/result.json');

// Minimal RFC4180-ish CSV row splitter (handles quoted fields and escaped quotes).
function splitCsvLine(line) {
  const fields = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"') {
        if (line[i + 1] === '"') {
          field += '"';
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        field += char;
      }
    } else if (char === '"') {
      inQuotes = true;
    } else if (char === ',') {
      fields.push(field);
      field = '';
    } else {
      field += char;
    }
  }

  fields.push(field);
  return fields.map((value) => value.trim());
}

function parseCsv(text) {
  const lines = text
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0);

  if (lines.length === 0) return { header: [], rows: [] };

  const header = splitCsvLine(lines[0]).map((name) => name.toLowerCase());
  const rows = lines.slice(1).map((line) => {
    const cells = splitCsvLine(line);
    return Object.fromEntries(header.map((name, index) => [name, cells[index] ?? '']));
  });

  return { header, rows };
}

function summarize(csvText) {
  const { header, rows } = parseCsv(csvText);

  if (!header.includes('category') || !header.includes('amount')) {
    throw new Error('CSV must contain "category" and "amount" columns');
  }

  const byCategory = {};
  let total = 0;

  for (const row of rows) {
    const category = row.category;
    const amount = Number(row.amount);

    if (!Number.isFinite(amount)) {
      throw new Error(`Invalid amount for category "${category}": ${row.amount}`);
    }

    byCategory[category] = (byCategory[category] ?? 0) + amount;
    total += amount;
  }

  return {
    byCategory: Object.fromEntries(
      Object.entries(byCategory).map(([category, sum]) => [category, Number(sum.toFixed(10))]),
    ),
    total: Number(total.toFixed(10)),
    rowCount: rows.length,
  };
}

const csvText = readFileSync(inputPath, 'utf8');
const summary = summarize(csvText);

mkdirSync(dirname(outputPath), { recursive: true });
writeFileSync(outputPath, `${JSON.stringify(summary, null, 2)}\n`, 'utf8');

console.log(JSON.stringify(summary, null, 2));
console.log(`\nWrote ${outputPath}`);
